/**
 * Global military infrastructure & nuclear facilities dataset
 * Sources: DoD base structure reports, SIPRI, FAS Nuclear Notebook,
 * IAEA PRIS, GlobalSecurity.org, open-source satellite analysis (OSINT)
 */

export type FacilityType =
  | 'airbase' | 'naval_base' | 'army_base' | 'marine_base'
  | 'nuclear_weapons' | 'nuclear_power'
  | 'missile_defense' | 'intelligence' | 'training' | 'logistics' | 'space'

export interface MilitaryFacility {
  id:          string
  name:        string
  type:        FacilityType
  operator:    string   // nation that operates it
  host:        string   // nation where physically located
  lat:         number
  lng:         number
  personnel?:  number
  status:      'active' | 'suspected' | 'proposed' | 'decommissioned'
  notes:       string
  nuclear?:    boolean  // nuclear-capable / nuclear-weapons storage
  since?:      string
}

export const FACILITY_COLORS: Record<FacilityType, string> = {
  airbase:          '#00c8ff',
  naval_base:       '#0055ff',
  army_base:        '#00cc55',
  marine_base:      '#cc3300',
  nuclear_weapons:  '#ff0033',
  nuclear_power:    '#ffdd00',
  missile_defense:  '#ff6600',
  intelligence:     '#aa00ff',
  training:         '#448866',
  logistics:        '#336699',
  space:            '#00ffaa',
}

